/** Local imported asset ownership and explicit compatibility texture sources. */
export async function createForestAssets(runtime,manifest,{imageFactory=()=>new Image()}={}){const {B,scene}=runtime,entries=new Set(),images=new Map();let serial=0;
 async function image(url){if(!images.has(url))images.set(url,new Promise((resolve,reject)=>{const i=imageFactory();i.onload=()=>{if(typeof document==='undefined')return resolve(i);const surface=document.createElement('canvas');surface.width=Math.min(512,i.width);surface.height=Math.round(i.height*surface.width/i.width);const c=surface.getContext('2d');c.filter='brightness(82%) saturate(82%)';c.drawImage(i,0,0,surface.width,surface.height);resolve(surface);};i.onerror=()=>reject(Error('Could not decode local texture '+url));i.src=url;}));return images.get(url);}
 if(runtime.software){const urls=[...new Set(Object.values(manifest.models).flatMap(m=>Object.values(m.textures).map(t=>t.url)))];await Promise.all(urls.map(image));}
 const loaded=new Map();await Promise.all(Object.entries(manifest.models).map(async([key,m])=>loaded.set(key,await runtime.assets.load(m.url))));
 async function decorate(mesh,key){mesh.isPickable=false;mesh.receiveShadows=true;const maps=manifest.models[key]?.textures||{},name=mesh.material?.name||'',map=maps[name]||Object.entries(maps).find(([k])=>(name.endsWith(k)||name.startsWith(k+'#')))?.[1];if(runtime.software&&map)mesh.metadata={...mesh.metadata,softwareTexture:{...map,image:await image(map.url)}};}
 function spawn(key,{x=0,y=0,z=0,scale=1,angle=0}={}){const container=loaded.get(key);if(!container)throw Error('Missing forest asset '+key);const id='forest'+(++serial)+':',entry=container.instantiateModelsToScene(n=>id+n,false,{doNotInstantiate:runtime.software}),root=new B.TransformNode(id+'placement',scene);entry.rootNodes.forEach(n=>n.parent=root);root.position.set(x,y,z);root.scaling.setAll(scale);root.rotation.y=angle;const meshes=root.getChildMeshes();for(const m of meshes){m.isPickable=false;m.receiveShadows=true;const maps=manifest.models[key].textures,map=maps[m.material?.name]||Object.entries(maps).find(([n])=>(m.material?.name.endsWith(n)||m.material?.name.startsWith(n+'#')))?.[1];if(runtime.software&&map)images.get(map.url).then(im=>{if(!m.isDisposed())m.metadata={...m.metadata,softwareTexture:{...map,image:im}};});}const item={root,meshes,key,entry,dispose(){entry.dispose();root.dispose();entries.delete(item);}};entries.add(item);return item;}
 return{spawn,decorate,image,loaded,dispose(){for(const e of [...entries])e.dispose();images.clear();loaded.clear();}};
}
